const getStorage = (key: string, fallback: unknown = null) => {
  const item = localStorage.getItem(key)

  return item !== null ? JSON.parse(item) : fallback
}

const setStorage = (key: string, value: unknown) => {
  localStorage.setItem(key, JSON.stringify(value))
}

export function WithFilters(): JSX.Element {
  const [sort, setSort] = useState<SortOptions>(() => ({
    direction: Directions.Ascending,
    key: 'name',
  }))
  const [filters, setFilters] = useState<
    { key: string; filter: { value: string; checked: boolean }[] }[]
  >(() =>
    getStorage('DenseNotSelectableWithFilters-filters', [
      {
        key: 'visibility',
        filter: [
          { value: '0', checked: true },
          { value: '1', checked: false },
          { value: '2', checked: false },
        ],
      },
    ]),
  )
  const [search, setSearch] = useState(() => '')
  const [options, setOptions] = useState(() => ({ page: 1, limit: 50 }))

  const handleChangePagination: HandlesPaginationChange = ({ page, limit }) => {
    setOptions({ page, limit })
  }

  const handleChangeSearch = (event: ChangeEvent<HTMLInputElement>) => {
    setSearch(event.target.value)
  }

  const handleChangeSort = (event: SortOptions) => {
    setSort(event)
  }

  const handleFilterChange: FilterEventHandler = ({
    columnKey,
    value,
    checked,
  }) => {
    const newFilters = filters.map((column) => {
      if (column.key === columnKey) {
        column.filter.map((filter) => {
          if (filter.value === value) {
            filter.checked = checked
          }

          return filter
        })
      }

      return column
    })

    setFilters(newFilters)
    setStorage('DenseNotSelectableWithFilters-filters', newFilters)
  }

  const filteredRows = seek(rows, search)
  const slicedRows = slice(arrange(filteredRows, sort), options)

  return (
    <Table
      columns={columnsWithFilter}
      onFilterChange={handleFilterChange}
      onSort={handleChangeSort}
      rows={slicedRows}
      storageKey="WithFilters"
      total={filteredRows.length}
    >
      <Table.Header>
        <Table.Title>Staff</Table.Title>
        <Table.GlobalActions>
          <Button startAdornment={ExpandMore} variant="outlined">
            CSV
          </Button>
          <Button color="primary" startAdornment={Add}>
            New
          </Button>
        </Table.GlobalActions>
      </Table.Header>
      <Table.Toolbar>
        <Table.Pagination onChange={handleChangePagination} />
        <Table.Search onChange={handleChangeSearch} />
      </Table.Toolbar>
    </Table>
  )
}

