export function SimplePagination(): JSX.Element {
  const { loading, start: startLoading } = useLoadingTimer(1000)
  const [sort, setSort] = useState<SortOptions>({
    direction: Directions.Ascending,
    key: 'name',
  })
  const [search, setSearch] = useState('')
  const [options, setOptions] = useState({ page: 1, limit: 50 })
  const totalRef = useRef<number | undefined>(undefined)
  const [refresh, setRefresh] = useState(0)

  const handleChangePagination: HandlesPaginationChange = ({
    page,
    limit,
  }: {
    page: number
    limit: number
  }) => {
    startLoading()
    setOptions({ page, limit })
  }

  const handleChangeSearch = (event: ChangeEvent<HTMLInputElement>) => {
    setSearch(event.target.value)
  }

  const handleChangeSort = (event: SortOptions) => {
    setSort(event)
  }

  const filteredRows = seek(rows, search)
  const arrangedRows = arrange(filteredRows, sort)

  const simulatedTotal =
    typeof totalRef.current === 'number'
      ? totalRef.current
      : arrangedRows.length
  const effectiveRows = arrangedRows.slice(0, simulatedTotal)

  const { page, limit } = options
  const start = (page - 1) * limit
  const end = start + limit
  const rowsWithSentinel = effectiveRows.slice(start, end + 1)

  const isShrunk = typeof totalRef.current === 'number'

  return (
    <Table
      columns={columns}
      key={refresh}
      loading={loading}
      onSort={handleChangeSort}
      pagination="simple"
      rows={rowsWithSentinel}
      selectable
      storageKey="DefaultSelectable"
    >
      <Table.Header>
        <Table.Title>Staff</Table.Title>
        <Table.GlobalActions>
          <Button
            onClick={() => {
              if (isShrunk) {
                totalRef.current = undefined
                setRefresh((n) => n + 1)
              } else {
                totalRef.current = 10
              }
            }}
            variant="outlined"
          >
            {isShrunk
              ? 'Restore full dataset'
              : 'Simulate reduced results on next fetch (cap to 10)'}
          </Button>
        </Table.GlobalActions>
      </Table.Header>
      <Table.Toolbar>
        <Table.Pagination onChange={handleChangePagination} />
        <Table.Search onChange={handleChangeSearch} />
      </Table.Toolbar>
    </Table>
  )
}

export function ExternalSelectionControl(): JSX.Element {
  const [sort] = useState<SortOptions>(() => ({
    direction: Directions.Ascending,
    key: 'name',
  }))
  const [options] = useState({ page: 1, limit: 50 })
  const [selectedIds, setSelectedIds] = useState<string[]>([])

  const slicedRows = slice(arrange(rows, sort), options)

  const handleSelectFirstThree = () => {
    setSelectedIds(slicedRows.slice(0, 3).map((row) => row.id))
  }

  const handleSelectAll = () => {
    setSelectedIds(slicedRows.map((row) => row.id))
  }

  const handleClearSelection = () => {
    setSelectedIds([])
  }

  return (
    <Table
      columns={columns}
      onSelect={(selected) => setSelectedIds(selected.map((row) => row.id))}
      rows={slicedRows}
      selectable
      selectedIds={selectedIds}
      storageKey="ExternalSelectionControl"
      total={rows.length}
    >
      <Table.Header>
        <Table.Title>Staff</Table.Title>
        <Table.GlobalActions>
          <Button onClick={handleSelectFirstThree} variant="outlined">
            Select first 3
          </Button>
          <Button onClick={handleSelectAll} variant="outlined">
            Select all
          </Button>
          <Button onClick={handleClearSelection} variant="outlined">
            Clear
          </Button>
        </Table.GlobalActions>
      </Table.Header>
    </Table>
  )
}
